pub(super) fn validate_point_cloud(points: &[Point]) -> Result<(), TetrahedralizationError> {
    let mut errors = Vec::new();
    let mut seen: HashMap<(u64, u64, u64), usize> = HashMap::new();
    if points.is_empty() {
        errors.push(TetrahedralizationInputError::EmptyPointSet);
    } else if points.len() < 4 {
        errors.push(TetrahedralizationInputError::InsufficientPoints {
            provided: points.len(),
            required: 4,
        });
    }

    for (index, point) in points.iter().enumerate() {
        if !point.x.is_finite() || !point.y.is_finite() || !point.z.is_finite() {
            errors.push(TetrahedralizationInputError::NonFinitePoint { index });
        }
        let key = (
            canonical_zero_bits(point.x),
            canonical_zero_bits(point.y),
            canonical_zero_bits(point.z),
        );
        if let Some(&first) = seen.get(&key) {
            errors.push(TetrahedralizationInputError::DuplicatePoint {
                first,
                second: index,
            });
        } else {
            seen.insert(key, index);
        }
    }

    // Find one non-degenerate oriented simplex with a linear scan. This avoids
    // the O(n⁴) all-quadruple scan and keeps validation bounded even for large
    // collinear/coplanar pathological inputs.
    if errors.is_empty() {
        let anchor = points[0];
        let Some(b) = points.iter().position(|point| *point != anchor) else {
            errors.push(TetrahedralizationInputError::DegeneratePointSet);
            return Err(TetrahedralizationError::InvalidInput {
                diagnostics: Box::new(TetrahedralizationInputDiagnostics { errors }),
            });
        };
        let Some(c) = points.iter().enumerate().find_map(|(index, point)| {
            (index != b && triangle_area_3d(&anchor, &points[b], point) > 0.0).then_some(index)
        }) else {
            errors.push(TetrahedralizationInputError::DegeneratePointSet);
            return Err(TetrahedralizationError::InvalidInput {
                diagnostics: Box::new(TetrahedralizationInputDiagnostics { errors }),
            });
        };
        let non_coplanar = points.iter().enumerate().any(|(index, point)| {
            index != b && index != c && orient3d(&[anchor, points[b], points[c], *point]) != 0.0
        });
        if !non_coplanar {
            errors.push(TetrahedralizationInputError::DegeneratePointSet);
        }
    }

    if errors.is_empty() {
        Ok(())
    } else {
        Err(TetrahedralizationError::InvalidInput {
            diagnostics: Box::new(TetrahedralizationInputDiagnostics { errors }),
        })
    }
}

pub(super) fn validate_recovered_constraints_without_steiner(
    points: &[Point],
    facets: &[RecoveredFacet],
) -> bool {
    let (nodes, tets) = run_delaunay(points);
    let mut recovery = FlipRecoveryMesh::new(nodes, tets);
    recovery.recover_edges_by_flips(facets);
    recovery.recover_facets_by_flips(facets);

    missing_constraint_edge(facets, &recovery.edge_set()).is_none()
        && facets
            .iter()
            .all(|facet| recovery.face_set().contains(&sorted3(facet.nodes)))
}

pub(super) fn validate_surface_input(
    points: &[Point],
    facets: &[[usize; 3]],
    facet_markers: Option<&[i32]>,
) -> Result<(), TetrahedralizationError> {
    let mut errors = Vec::new();
    if points.is_empty() {
        errors.push(TetrahedralizationInputError::EmptyPointSet);
    } else if points.len() < 4 {
        errors.push(TetrahedralizationInputError::InsufficientPoints {
            provided: points.len(),
            required: 4,
        });
    }
    for (index, point) in points.iter().enumerate() {
        if !point.x.is_finite() || !point.y.is_finite() || !point.z.is_finite() {
            errors.push(TetrahedralizationInputError::NonFinitePoint { index });
        }
    }

    if let Some(markers) = facet_markers
        && markers.len() != facets.len()
    {
        errors.push(TetrahedralizationInputError::MarkerCountMismatch {
            facets: facets.len(),
            markers: markers.len(),
        });
    }

    let mut edge_incidence: HashMap<[usize; 2], Vec<usize>> = HashMap::new();
    for (facet_index, facet) in facets.iter().enumerate() {
        for (node_position, &node_index) in facet.iter().enumerate() {
            if node_index >= points.len() {
                errors.push(TetrahedralizationInputError::FacetIndexOutOfBounds {
                    facet_index,
                    node_position,
                    node_index,
                    point_count: points.len(),
                });
            }
        }
        if facet[0] == facet[1] || facet[1] == facet[2] || facet[2] == facet[0] {
            errors.push(TetrahedralizationInputError::RepeatedFacetNode { facet_index });
            continue;
        }
        if facet.iter().all(|&index| index < points.len())
            && triangle_area_squared(points[facet[0]], points[facet[1]], points[facet[2]]) <= 1e-28
        {
            errors.push(TetrahedralizationInputError::DegenerateFacet { facet_index });
        }
        for edge in [
            sorted2([facet[0], facet[1]]),
            sorted2([facet[1], facet[2]]),
            sorted2([facet[2], facet[0]]),
        ] {
            edge_incidence.entry(edge).or_default().push(facet_index);
        }
    }
    let mut edge_entries: Vec<_> = edge_incidence.into_iter().collect();
    edge_entries.sort_unstable_by_key(|(edge, _)| *edge);
    for (edge, incident_facets) in edge_entries {
        if incident_facets.len() > 2 {
            errors.push(TetrahedralizationInputError::NonManifoldEdge {
                edge,
                incident_facets,
            });
        }
    }

    if errors.is_empty() {
        Ok(())
    } else {
        Err(TetrahedralizationError::InvalidInput {
            diagnostics: Box::new(TetrahedralizationInputDiagnostics { errors }),
        })
    }
}

pub(super) fn validate_generated_mesh(mesh: &Mesh) -> MeshValidityDiagnostics {
    let mut diagnostics = MeshValidityDiagnostics {
        empty_mesh: mesh.elements.is_empty(),
        ..MeshValidityDiagnostics::default()
    };
    for (element_index, element) in mesh.elements.iter().enumerate() {
        if element.nodes.len() < element.element_type.num_vertices()
            || element
                .vertices()
                .iter()
                .any(|&node_index| node_index >= mesh.nodes.len())
        {
            diagnostics.invalid_node_references.push(element_index);
        }
    }
    if diagnostics.invalid_node_references.is_empty() {
        diagnostics.degenerate_elements = find_degenerate_elements(mesh, 0.0);
        diagnostics.inverted_elements = check_orientation(mesh);
        diagnostics.non_manifold_faces = check_manifold(mesh).non_manifold_faces;
    }
    diagnostics
}

pub(super) fn validate_box_input(
    x_min: f64,
    x_max: f64,
    y_min: f64,
    y_max: f64,
    z_min: f64,
    z_max: f64,
    resolution: usize,
) -> Result<(), TetrahedralizationError> {
    let mut errors = Vec::new();
    if resolution == 0 {
        errors.push(TetrahedralizationInputError::ZeroResolution);
    }
    for (axis, min, max) in [
        ('x', x_min, x_max),
        ('y', y_min, y_max),
        ('z', z_min, z_max),
    ] {
        if !min.is_finite() || !max.is_finite() {
            errors.push(TetrahedralizationInputError::NonFiniteBoxBound { axis });
        } else if min >= max {
            errors.push(TetrahedralizationInputError::InvalidBoxBounds { axis });
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(TetrahedralizationError::InvalidInput {
            diagnostics: Box::new(TetrahedralizationInputDiagnostics { errors }),
        })
    }
}

/// Run a post-hoc sanity check on a Delaunay tet mesh. Returns counts of
/// degenerate / inverted / non-Delaunay tets. The check is O(N²) in the
/// number of tets and is intended for diagnostics, not hot paths.
pub fn validate_delaunay(mesh: &Mesh) -> DelaunayDiagnostics {
    let mut report = DelaunayDiagnostics::default();
    let mut tet_indices: Vec<[usize; 4]> = Vec::new();
    for elem in &mesh.elements {
        if elem.element_type == ElementType::Tetrahedron {
            tet_indices.push([elem.nodes[0], elem.nodes[1], elem.nodes[2], elem.nodes[3]]);
        }
    }

    for tet in &tet_indices {
        let verts = [
            mesh.nodes[tet[0]],
            mesh.nodes[tet[1]],
            mesh.nodes[tet[2]],
            mesh.nodes[tet[3]],
        ];
        let signed = orient3d(&verts);
        if signed.abs() < 1e-14 {
            report.degenerate_tets += 1;
        }
        // `Mesh` stores tets with positive FEM/Jacobian volume, while
        // Shewchuk's orient3d predicate uses the opposite determinant sign.
        if signed > 1e-14 {
            report.inverted_tets += 1;
        }
    }

    // Non-Delaunay check: for each tet, verify no other vertex lies strictly
    // inside its circumsphere. Quadratic, hence diagnostic-only.
    for tet in &tet_indices {
        let verts = [
            mesh.nodes[tet[0]],
            mesh.nodes[tet[1]],
            mesh.nodes[tet[2]],
            mesh.nodes[tet[3]],
        ];
        for (node_idx, p) in mesh.nodes.iter().enumerate() {
            if tet.contains(&node_idx) {
                continue;
            }
            if in_circumsphere(p, &verts) {
                report.non_delaunay_violations += 1;
                break; // count each tet at most once
            }
        }
    }

    report
}
